const $=s=>document.querySelector(s), app=$('#app');
const categories=['Все','Иммунитет','Основы микробиологии','Диагностика','Инфекции'];
const custom=[
{match:'неспецифический иммунитет',simple:'Представь организм крепостью. Кожа и слизистые — стены, слёзы и лизоцим — защитные вещества, фагоциты — патруль, а комплемент — система сигнализации и атаки. Эта защита срабатывает быстро и не требует заранее узнавать конкретного врага.',scientific:'Врождённый (неспецифический) иммунитет объединяет анатомические барьеры, растворимые медиаторы (лизоцим, комплемент), клеточные механизмы (фагоциты, NK-клетки) и воспалительный ответ. Комплемент может активироваться классическим, лектиновым и альтернативным путями; итоговые эффекты включают опсонизацию, воспаление и образование мембраноатакующего комплекса.',steps:['🧱|Кожа и слизистые','🧪|Лизоцим и комплемент','🛡️|Фагоцитоз','✨|Устранение угрозы'],q:[['Что относится к первой линии врождённой защиты?',['Неповреждённая кожа','Иммунологическая память','Антитела после вакцинации'],0,'Кожа физически препятствует проникновению микробов.'],['Как действует лизоцим?',['Разрушает пептидогликан клеточной стенки бактерий','Синтезирует антитела','Создаёт споры'],0,'Лизоцим расщепляет связи в пептидогликане, особенно у чувствительных бактерий.'],['Что делает комплемент?',['Помогает опсонизации и лизису','Образует бактериальные споры','Создаёт антибиотики'],0,'Белки комплемента помогают распознавать, привлекать клетки и повреждать мембраны.']]},
{match:'дыхание клетки',simple:'Микробам нужна энергия. Одни используют кислород, другие живут без него, а третьи могут переключаться. Как электростанция, клетка выбирает доступный способ получения энергии.',scientific:'По отношению к O₂ выделяют облигатных аэробов, облигатных анаэробов, факультативных анаэробов, аэротолерантных анаэробов и микроаэрофилов. Аэробное дыхание использует O₂ как конечный акцептор электронов; при анаэробном дыхании используются другие акцепторы, а брожение отличается механизмом регенерации переносчиков электронов.',steps:['🌬️|Есть кислород','⚙️|Электрон-транспортная цепь','⚡|Образование АТФ'],q:[['Кто способен расти с кислородом и без него?',['Факультативный анаэроб','Облигатный аэроб','Облигатный анаэроб'],0,'Факультативные анаэробы переключают энергетический обмен в зависимости от условий.'],['Конечный акцептор электронов при аэробном дыхании?',['Кислород','Глюкоза','ДНК'],0,'В аэробной дыхательной цепи конечный акцептор электронов — O₂.']]},
{match:'инфекция, инфекционный',simple:'Заражение — это не всегда болезнь. Микроб может попасть в организм, но симптомы появятся только при определённых условиях. Важно различать сам факт взаимодействия с возбудителем, процесс и клиническую болезнь.',scientific:'Инфекционный процесс — взаимодействие возбудителя с восприимчивым макроорганизмом в определённых условиях. Инфекционная болезнь — клинически выраженная форма этого процесса. Выделяют экзогенные и эндогенные инфекции, моно- и смешанные, острые и хронические, манифестные и бессимптомные.',steps:['🦠|Контакт с возбудителем','🚪|Проникновение','🔁|Размножение','🩺|Исход / симптомы'],q:[['Всегда ли инфицирование сопровождается симптомами?',['Нет','Да','Только у животных'],0,'Инфекция может протекать бессимптомно.'],['Что означает смешанная инфекция?',['Участие нескольких возбудителей','Повторное заражение тем же микробом','Только вирусная инфекция'],0,'Смешанная инфекция вызывается несколькими микроорганизмами.']]},
{match:'питание метаболизм',simple:'Бактерии похожи на мини-фабрики: получают сырьё, превращают его в энергию и строительные детали. Одни питаются готовыми органическими веществами, другие используют CO₂.',scientific:'Метаболизм включает катаболизм (получение энергии и предшественников) и анаболизм (биосинтез). По источнику углерода различают автотрофов и гетеротрофов; по источнику энергии — фототрофов и хемотрофов. Эти классификации описывают разные свойства и могут комбинироваться.',steps:['🍽️|Питательные вещества','🔧|Катаболизм','⚡|АТФ','🧬|Анаболизм'],q:[['Что такое катаболизм?',['Распад веществ с высвобождением энергии','Синтез сложных молекул','Деление клетки'],0,'Катаболические реакции расщепляют вещества и обеспечивают клетку энергией.'],['Основной источник углерода автотрофов?',['CO₂','Готовые белки','Только глюкоза'],0,'Автотрофы используют неорганический углерод, прежде всего CO₂.']]},
{match:'стерилизац',simple:'Дезинфекция уменьшает количество опасных микробов, а стерилизация уничтожает все жизнеспособные микроорганизмы, включая бактериальные споры. Выбор метода зависит от материала.',scientific:'Стерилизация — валидированный процесс устранения жизнеспособных микроорганизмов, включая споры. Влажный жар в автоклаве обеспечивает эффективную передачу тепла; сухожаровые, фильтрационные и иные методы применяются с учётом свойств объекта. Конкретный режим определяется оборудованием и протоколом.',steps:['🧫|Объект','🌡️|Подходящий метод','⏱️|Контроль процесса','✅|Стерильный материал'],q:[['Что отличает стерилизацию от дезинфекции?',['Устранение всех жизнеспособных микроорганизмов, включая споры','Только мытьё водой','Удаление лишь видимой грязи'],0,'Стерилизация предъявляет более строгие требования, чем дезинфекция.']]},
{match:'туберкулез',simple:'Микобактерии туберкулёза отличаются необычной богатой липидами клеточной оболочкой. Из-за неё для окраски и диагностики нужны специальные методы.',scientific:'Mycobacterium tuberculosis complex — кислотоустойчивые бактерии с богатой миколовыми кислотами оболочкой. Для диагностики применяют микроскопию кислотоустойчивых бактерий, молекулярные тесты и культуральные исследования; выбор алгоритма зависит от вида пациента, образца и локальных рекомендаций.',steps:['🧪|Образец','🔬|Микроскопия','🧬|Молекулярный тест','📋|Интерпретация'],q:[['Почему микобактерии кислотоустойчивы?',['Из-за липидов и миколовых кислот в клеточной оболочке','Из-за отсутствия ДНК','Из-за жгутиков'],0,'Особая липидная клеточная оболочка определяет кислотоустойчивость.']]},
{match:'столбняка и ботулизма',simple:'Столбняк и ботулизм связаны с нейротоксинами клостридий, но действуют по-разному: при столбняке преобладают спазмы, при ботулизме — вялый паралич.',scientific:'Clostridium tetani вырабатывает тетаноспазмин, нарушающий высвобождение тормозных медиаторов, что ведёт к спастическому параличу. Ботулинический нейротоксин Clostridium botulinum блокирует высвобождение ацетилхолина в нервно-мышечном синапсе и вызывает вялый паралич.',steps:['🦠|Clostridium','🧪|Нейротоксин','🧠|Нервный синапс','⚠️|Нарушение движения'],q:[['Какой тип паралича характерен для ботулизма?',['Вялый','Спастический','Паралича не бывает'],0,'Ботулотоксин препятствует высвобождению ацетилхолина и вызывает вялый паралич.'],['Какой тип паралича характерен для столбняка?',['Спастический','Вялый','Только сенсорный'],0,'Тетаноспазмин нарушает тормозную передачу и вызывает мышечные спазмы.']]},
{match:'антибиотик',simple:'Антибиотики мешают бактериям строить стенку, производить белки или выполнять другие важные функции. Против вирусов обычные антибактериальные препараты не работают.',scientific:'Антибактериальные препараты классифицируют по мишеням: синтез клеточной стенки, белка, нуклеиновых кислот, фолатный обмен и целостность мембраны. Эффективность зависит от чувствительности возбудителя, фармакокинетики и локализации инфекции.',steps:['💊|Препарат','🎯|Молекулярная мишень','⛔|Подавление роста'],q:[['На что действуют β-лактамные антибиотики?',['Синтез клеточной стенки','Синтез вирусного капсида','Ядро эритроцита'],0,'β-лактамы нарушают образование пептидогликана клеточной стенки.']]},
{match:"способы передачи инфекционных",simple:"Путь передачи — это маршрут, по которому возбудитель попадает от источника к восприимчивому организму. При контактном пути нужен непосредственный контакт или загрязнённые предметы; при алиментарном — пища или вода; при аэрогенном — частицы в воздухе. Профилактика должна разрывать именно тот путь, который характерен для инфекции.",scientific:"Механизм передачи включает выделение возбудителя из источника, пребывание во внешней среде или переносчике и внедрение в новый организм. Различают контактный, фекально-оральный, аэрогенный, трансмиссивный и вертикальный механизмы. Конкретный механизм определяется биологией возбудителя и условиями заражения."},
{match:"характеристика изолированных колоний",simple:"Колония — видимый результат размножения микроорганизмов на плотной среде. Оценивают размер, форму, край, поверхность, цвет и прозрачность. Одинаковый вид колоний ещё не доказывает, что это один и тот же микроорганизм: нужны дополнительные исследования.",scientific:"Колониальная морфология — первичный фенотипический признак культуры. Для выделения чистой культуры применяют рассев до изолированных колоний, затем пересев выбранной колонии с последующей проверкой чистоты микроскопией и другими методами. Морфология колонии не является самостоятельным критерием видовой идентификации."},
{match:"характер роста бактерий и грибов",simple:"На плотной питательной среде микробы обычно образуют колонии. В жидкой среде рост может выглядеть как помутнение, плёнка на поверхности или осадок. Внешний вид помогает выбрать дальнейший метод исследования, но не даёт окончательного диагноза.",scientific:"Характер роста зависит от вида микроорганизма, состава среды, температуры и доступности кислорода. На агаре оценивают колониальную морфологию; в бульоне — диффузное помутнение, поверхностную плёнку, хлопья и осадок. Результат интерпретируют вместе с микроскопией, биохимическими и при необходимости молекулярными тестами."},
{match:"иммунитет, стерильный",simple:"При стерильном иммунитете после выздоровления возбудитель удалён из организма, а защита может сохраняться. При нестерильном иммунитете защитное состояние связано с присутствием возбудителя или его персистенцией. Эти термины описывают связь иммунитета с сохранением возбудителя, а не «силу» защиты.",scientific:"Стерильный иммунитет предполагает элиминацию инфекционного агента при сохранении иммунологической защиты. Нестерильный (инфекционный) иммунитет поддерживается при персистенции возбудителя и может ослабевать после его удаления. Реальная устойчивость к повторному заражению зависит от возбудителя и типа иммунного ответа."},
{match:"отбор материала при инфекциях",simple:"Правильный анализ начинается до лаборатории: нужно взять материал из подходящего места, в нужный момент и безопасно доставить. Неправильный образец или нарушение хранения могут дать ложноотрицательный результат даже при хорошей лабораторной методике.",scientific:"Преаналитический этап включает выбор клинического материала с учётом локализации процесса, асептический отбор, маркировку, транспортную среду, температурный режим и сроки доставки. Затем выполняют микроскопию, посев, идентификацию и при показаниях определение чувствительности. Порядок зависит от подозреваемого возбудителя и действующих лабораторных протоколов."},
{match:"классификация бактерий по типу питания",simple:"Бактериям нужны источник углерода и энергия. Одни используют углекислый газ как источник углерода, другие — готовые органические вещества. Энергию можно получать из света или химических реакций. Поэтому способ питания описывают сразу по нескольким признакам.",scientific:"По источнику углерода различают автотрофов и гетеротрофов; по источнику энергии — фототрофов и хемотрофов; по донору электронов — литотрофов и органотрофов. Комбинации этих признаков описывают метаболический тип точнее, чем единственная бинарная классификация."},
{match:"дрожжи и плесени",simple:"Дрожжи чаще растут как отдельные клетки и размножаются почкованием; плесневые грибы формируют нити — гифы — и мицелий. Некоторые грибы могут вырабатывать микотоксины, которые опасны даже без активного роста гриба в организме.",scientific:"Дрожжевые формы преимущественно одноклеточные, плесневые — мицелиальные; существуют и диморфные грибы. Микотоксикозы связаны с поступлением токсичных вторичных метаболитов грибов, чаще с загрязнённым кормом или пищей. Микотоксикоз не равнозначен грибковой инфекции."},
{match:"сальмонеллы",simple:"Сальмонеллы — бактерии, которые могут вызывать кишечные и системные инфекции у животных и человека. Для лабораторного подтверждения важно не только обнаружить бактерию, но и правильно выбрать материал и метод исследования.",scientific:"Salmonella — род грамотрицательных факультативно-анаэробных палочек семейства Enterobacteriaceae. Патогенность и клинические проявления зависят от серовара и хозяина. Диагностика может включать бактериологическое выделение и идентификацию, серотипирование и молекулярные методы согласно диагностическому протоколу."}
];
const bad=/^(В зависимости от числа|По происхождению|По выраженности|Жив-го происх|Разрушающие рибосом|Огромная скорость|На обезжиренное|Физиологический раствор|Антиген|Агглютиноген|Исследуемое молоко)/i;
