custom.push(...[
{"match": "микоплазмозы", "simple": "Микоплазмы — очень мелкие бактерии без клеточной стенки. Поэтому препараты, которые нарушают построение стенки, против них неэффективны. Для подтверждения инфекции важно учитывать вид животного, признаки болезни и результаты лабораторного анализа.", "scientific": "Mycoplasma spp. относятся к бактериям класса Mollicutes и не имеют пептидогликановой клеточной стенки. Для диагностики применяют методы выявления возбудителя, включая ПЦР и культуральное исследование при подходящих условиях. Клиническое значение находки определяется видом микоплазмы, хозяином и местом отбора материала.", "q": [["Почему β-лактамные антибиотики обычно не действуют на микоплазмы?", ["У микоплазм нет пептидогликановой стенки", "Микоплазмы не содержат рибосом", "Все микоплазмы являются вирусами"], 0, "β-лактамы воздействуют на синтез пептидогликана, которого у микоплазм нет."]]},
{"match": "реакция преципитации по асколи", "simple": "Это лабораторная реакция, при которой растворимый антиген встречается со специфическими антителами и образует видимую линию осадка. Исторически реакцию Асколи применяли при исследовании материала на сибирскую язву. Результат обязательно оценивают вместе с контролями.", "scientific": "Термопреципитационная реакция Асколи основана на образовании преципитата при взаимодействии растворимых антигенов Bacillus anthracis со специфической иммунной сывороткой. Метод исторический, имеет ограничения специфичности и не заменяет современные подтверждающие методы. Работа с подозрительным материалом требует установленных мер биобезопасности.", "q": [["Что лежит в основе реакции преципитации?", ["Образование комплекса растворимого антигена и антитела", "Разрушение эритроцитов", "Рост колоний на агаре"], 0, "Преципитация возникает при формировании достаточно крупных иммунных комплексов."]]},
{"match": "лабораторная диагностика рожи свиней", "simple": "Рожа свиней — бактериальная инфекция, связанная с Erysipelothrix rhusiopathiae. Она может проявляться лихорадкой, характерными кожными изменениями и поражением суставов. Диагноз не ставят только по виду пятен: нужны лабораторные подтверждения.", "scientific": "Erysipelothrix rhusiopathiae — грамположительная неспорообразующая палочка, вызывающая у свиней острые, подострые и хронические формы болезни. Подтверждение может включать выделение и идентификацию возбудителя либо валидированные молекулярные методы с учётом клинических данных и материала. Специфическая профилактика основана на ветеринарных программах вакцинации.", "q": [["Какой возбудитель связан с рожей свиней?", ["Erysipelothrix rhusiopathiae", "Salmonella enterica", "Clostridium tetani"], 0, "Рожу свиней вызывает Erysipelothrix rhusiopathiae."]]},
{"match": "дерматомикозы", "simple": "Дерматомикозы — грибковые заболевания кожи и её придатков. Дерматофиты используют кератин, поэтому часто поражают волосы, шерсть, когти и поверхностные слои кожи. Похожая сыпь бывает и при других болезнях — необходима диагностика.", "scientific": "Дерматофитии вызывают кератинофильные грибы, в том числе представители родов Microsporum и Trichophyton. Диагностика опирается на клинические признаки, микроскопию волос и чешуек, культуральные и при наличии валидированных методик молекулярные исследования. Часть дерматофитий зоонозна.", "q": [["Почему дерматофиты часто поражают волосы и шерсть?", ["Они способны использовать кератин", "Они размножаются только в крови", "Им необходим гемоглобин"], 0, "Кератинофильные грибы способны колонизировать кератинизированные ткани."]]},
{"match": "реакция микроагглютинации", "simple": "Агглютинация — это склеивание частиц с антигенами при добавлении подходящих антител. В микроформате реакцию проводят в небольшом объёме, а результат оценивают по характеру осадка и контрольным пробам.", "scientific": "Реакции микроагглютинации основаны на специфическом связывании корпускулярных антигенов антителами с формированием видимых агрегатов. Методика, матрица и критерии положительности зависят от конкретной диагностической системы. Необходимы положительный и отрицательный контроли; неспецифическая агглютинация может приводить к ошибкам интерпретации.", "q": [["Что непосредственно вызывает агглютинацию?", ["Связывание частиц антителами", "Синтез ДНК бактерий", "Образование бактериальных спор"], 0, "Антитела связывают антигенные частицы в видимые агрегаты."]]},
{"match": "образование оболочек споры", "simple": "Спора помогает некоторым бактериям переживать неблагоприятные условия. При спорообразовании клетка последовательно формирует внутренние структуры и защитные оболочки. Спора — не способ размножения: из одной клетки возникает одна спора.", "scientific": "Эндоспорообразование у некоторых Firmicutes включает асимметричное деление, поглощение предспоры материнской клеткой, формирование коры и белковых оболочек, созревание и высвобождение эндоспоры. Дегидратация сердцевины и дипиколинат кальция участвуют в устойчивости. Эндоспора может прорастать при благоприятных условиях.", "q": [["Зачем бактерии образуют эндоспоры?", ["Для выживания при неблагоприятных условиях", "Для увеличения числа клеток путём деления спор", "Для фотосинтеза"], 0, "Эндоспора — форма сохранения жизнеспособности, а не механизм размножения."]]},
{"match": "эмкар", "simple": "Эмкар — опасная инфекция преимущественно крупного рогатого скота, вызывающая поражение мышц и тяжёлую интоксикацию. Возбудитель может сохраняться в виде спор. Болезнь требует ветеринарной диагностики и профилактики по местным правилам.", "scientific": "Эмфизематозный карбункул (blackleg) вызывается Clostridium chauvoei, спорообразующей анаэробной бактерией. Для заболевания характерны некротизирующий миозит и газообразование в поражённых тканях. Подтверждение основано на исследовании подходящего патологического материала в специализированной лаборатории; профилактика включает вакцинацию в неблагополучных регионах.", "q": [["Какой возбудитель вызывает эмкар?", ["Clostridium chauvoei", "Mycoplasma bovis", "Erysipelothrix rhusiopathiae"], 0, "Эмфизематозный карбункул связан с Clostridium chauvoei."]]},
{"match": "злокачественный отёк", "simple": "Злокачественный отёк — тяжёлая раневая инфекция, при которой анаэробные бактерии повреждают мягкие ткани и вызывают отёк и интоксикацию. Это не одно и то же, что эмкар, хотя признаки могут быть похожи.", "scientific": "Злокачественный отёк у животных — клостридиальная раневая инфекция, ассоциированная с различными видами Clostridium, в том числе C. septicum и C. novyi. Токсины вызывают некроз тканей и системные нарушения. Вид возбудителя уточняют лабораторно; дифференцируют с эмфизематозным карбункулом и другими причинами отёка.", "q": [["Что характерно для злокачественного отёка?", ["Анаэробная раневая инфекция мягких тканей", "Исключительно вирусная инфекция", "Нормальная реакция на вакцинацию"], 0, "Злокачественный отёк связан с токсигенными анаэробными бактериями, поражающими ткани."]]},
{"match": "антагонизм", "simple": "Микроорганизмы могут мешать росту друг друга: конкурировать за питательные вещества, изменять среду или выделять вещества, подавляющие соседей. Такое взаимодействие называют антагонизмом.", "scientific": "Микробный антагонизм — межмикробное взаимодействие, при котором один организм снижает рост или жизнеспособность другого за счёт конкуренции за ресурсы, продукции антимикробных метаболитов, изменения pH или других механизмов. Эффект зависит от среды и условий эксперимента.", "q": [["Что является примером микробного антагонизма?", ["Подавление роста конкурента антимикробным веществом", "Бесполое деление одной бактерии", "Образование двух идентичных клеток"], 0, "Антагонизм означает отрицательное влияние одного микроорганизма на другой."]]},
{"match": "ра на стекле", "simple": "Реакция агглютинации на стекле позволяет быстро проверить, склеиваются ли микробные частицы при контакте со специфической сывороткой. Важно сравнивать результат с контролем, иначе можно принять самопроизвольные хлопья за положительную реакцию.", "scientific": "Слайд-агглютинация — качественная серологическая реакция взаимодействия корпускулярного антигена со специфическими антителами. Интерпретация требует контроля спонтанной аутоагглютинации и использования валидированных реагентов. Метод не всегда обеспечивает окончательную идентификацию без дополнительных тестов.", "q": [["Зачем нужен контроль при агглютинации на стекле?", ["Чтобы отличить специфическую реакцию от самоагглютинации", "Чтобы ускорить деление бактерий", "Чтобы измерить количество вирусной РНК"], 0, "Контроль помогает исключить ложноположительный результат из-за неспецифических хлопьев."]]},
]);
// Curated lessons recovered from fragmentary PDF headings. The underlying PDF excerpt is retained.
const recoveredLessons=[
 {match:'шаровидная - кокки',title:'Морфология бактерий: кокки',simple:'Кокки — бактерии округлой формы. После деления они могут располагаться по одной, парами, цепочками или скоплениями. Расположение помогает описать препарат, но само по себе не определяет вид.',scientific:'Кокки — морфологическая группа бактерий с приблизительно сферическими клетками. Плоскость деления и сохранение связей между дочерними клетками формируют диплококки, стрептококковые цепочки, стафилококковые скопления и другие варианты. Морфология оценивается вместе с окраской и результатами идентификации.',q:[['Что означает термин «диплококки»?',['Пара округлых клеток','Палочки со спорами','Цепь из палочек'],0,'Приставка «дипло-» указывает на парное расположение кокков.'],['Можно ли определить вид бактерии только по расположению кокков?',['Нет, нужны дополнительные признаки','Да, всегда','Да, если есть две клетки'],0,'Расположение клеток — лишь один из фенотипических признаков.']]},
 {match:'палочковидные - цилиндрической',title:'Морфология бактерий: палочки',simple:'Палочковидные бактерии имеют вытянутую форму. Они различаются по длине, толщине, расположению и способности образовывать споры. Форма — полезная подсказка при микроскопии, но не окончательный диагноз.',scientific:'Бациллярная морфология характеризуется преобладанием продольного размера клетки. Палочки могут быть короткими или длинными, располагаться одиночно, попарно либо цепочками. Спорообразование свойственно отдельным таксонам и не является универсальным признаком палочковидных бактерий.',q:[['Все ли палочковидные бактерии образуют эндоспоры?',['Нет, лишь некоторые','Да, все','Споры бывают только у кокков'],0,'Эндоспоры образуют лишь определённые группы бактерий.']]},
 {match:'лимфоциты',title:'Лимфоциты и адаптивный иммунитет',simple:'B-лимфоциты могут превращаться в клетки, производящие антитела. T-лимфоциты помогают управлять иммунным ответом или уничтожают заражённые клетки. Эти клетки участвуют в специфической защите и иммунной памяти.',scientific:'B-лимфоциты обеспечивают гуморальный компонент адаптивного иммунитета через дифференцировку в плазматические клетки и клетки памяти. CD4+ T-клетки координируют иммунный ответ, а CD8+ цитотоксические T-клетки способны уничтожать клетки с распознанным антигеном в контексте MHC I.',q:[['Какие клетки непосредственно секретируют большое количество антител?',['Плазматические клетки','Эритроциты','Нейтрофилы'],0,'Плазматические клетки образуются при дифференцировке активированных B-лимфоцитов.'],['Какая функция характерна для цитотоксических T-лимфоцитов?',['Уничтожение заражённых клеток','Синтез пептидогликана','Образование эндоспор'],0,'Цитотоксические T-клетки распознают и уничтожают определённые клетки-мишени.']]},
 {match:'моноциты – макрофаги',title:'Моноциты, макрофаги и презентация антигена',simple:'Моноциты циркулируют в крови; часть из них превращается в тканевые макрофаги. Макрофаги поглощают частицы и могут показывать фрагменты антигена T-лимфоцитам, связывая врождённую и адаптивную защиту.',scientific:'Моноциты — клетки миелоидного ряда; тканевые макрофаги имеют разнообразное происхождение и функции. Макрофаги осуществляют фагоцитоз, секрецию цитокинов и презентацию обработанных антигенных пептидов в комплексе с MHC II CD4+ T-клеткам. Профессиональными антигенпрезентирующими клетками также являются дендритные клетки и B-лимфоциты.',q:[['Как макрофаги помогают T-хелперам распознать антиген?',['Представляют пептиды в комплексе с MHC II','Превращают антиген в антибиотик','Образуют бактериальные споры'],0,'Презентация пептида на MHC II участвует в активации CD4+ T-клеток.']]}
];
for(const entry of recoveredLessons){const t=TOPICS.find(x=>x.title.toLowerCase().includes(entry.match));if(t){t.title=entry.title;custom.push({...entry,match:entry.title.toLowerCase()})}}
// Repair visibly truncated source headings without changing their source excerpts.
for(const t of TOPICS){
 if(t.title.startsWith('Лабораторная диагностика рожи свиней.'))t.title='Лабораторная диагностика рожи свиней';
 if(t.title.startsWith('Стерилизация текучим паром.'))t.title='Стерилизация текучим паром';
 if(t.title.startsWith('Тиндализация.'))t.title='Тиндализация (дробная стерилизация)';
 if(t.title==='Пит среды. Стерилизация их.')t.title='Питательные среды и стерилизация';
}
// Fragmentary headings remain available in the full original exam tickets, but are not presented as independent lessons.
const topics=TOPICS.filter(t=>!bad.test(t.title)&&t.body.length>130&&custom.some(c=>t.title.toLowerCase().includes(c.match))).map((t,i)=>({...t,uid:i,custom:custom.find(c=>t.title.toLowerCase().includes(c.match))}));
const topicId=t=>'topic:'+t.id;
let filter='Все',query='',current=null,mode='simple',test=[],idx=0,score=0,locked=false,review=[];
let bookmarks={},difficult={},flashIndex=0,flashShown=false,spaced={};try{bookmarks=JSON.parse(localStorage.getItem('micro-bookmarks')||'{}');difficult=JSON.parse(localStorage.getItem('micro-difficult')||'{}');spaced=JSON.parse(localStorage.getItem('micro-spaced')||'{}')}catch(e){}
function persistStudy(){try{localStorage.setItem('micro-bookmarks',JSON.stringify(bookmarks));localStorage.setItem('micro-difficult',JSON.stringify(difficult));localStorage.setItem('micro-spaced',JSON.stringify(spaced))}catch(e){}}
function excerpts(t){let raw=t.body.replace(/\s+/g,' ').replace(/(?:^|\s)(?:\d+[.)]|[-•])\s+/g,' ');let arr=raw.split(/(?<=[.!?])\s+(?=[А-ЯA-ZЁ])/).map(x=>x.trim()).filter(x=>x.length>=65&&x.length<=310&&!/https?:|рисунок|таблица/i.test(x));return [...new Set(arr)].slice(0,12)}
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let progress={};try{progress=JSON.parse(localStorage.getItem('micro-progress')||'{}')}catch(e){}
function save(){try{localStorage.setItem('micro-progress',JSON.stringify(progress))}catch(e){}}

// One-time migration: old release used position-based indexes; now saves use immutable original topic IDs.
(function migrateTopicStorage(){
 try{
  if(localStorage.getItem('micro-topic-storage-v2')==='done')return;
  for(const [name,obj] of [['progress',progress],['bookmarks',bookmarks],['difficult',difficult]]){
   topics.forEach(t=>{if(Object.prototype.hasOwnProperty.call(obj,String(t.uid)))obj[topicId(t)]=obj[t.uid]});
   topics.forEach(t=>delete obj[t.uid]);
  }
  const updated={};for(const [key,val] of Object.entries(spaced)){
   const m=/^(\d+):(\d+)$/.exec(key);
   if(m&&topics[+m[1]])updated[topicId(topics[+m[1]])+':'+m[2]]=val;
   else updated[key]=val;
  }
  spaced=updated;
  save();persistStudy();localStorage.setItem('micro-topic-storage-v2','done');
 }catch(e){console.warn('MICRO LAB: сохранение прогресса недоступно',e)}
})();

function baseHome(){current=null;const done=topics.filter(t=>progress[topicId(t)]).length;app.innerHTML=`<div class="hero"><div><div class="eyebrow">Твоя лаборатория знаний</div><h1>Микробиология.<br>Понять, а не зазубрить.</h1><p class="muted">Теория на двух уровнях сложности, интерактивные модели, тесты с разбором ошибок и прогресс обучения. По материалам экзаменационных билетов.</p><div class="stats"><div class="stat"><strong>${topics.length}</strong><small>тем из PDF</small></div><div class="stat"><strong>${done}</strong><small>тем пройдено</small></div><div class="stat"><strong>${Math.round(done/topics.length*100)}%</strong><small>прогресс</small></div></div></div><div class="panel hero-art"><div class="microbe"></div></div></div><div class="study-shortcuts"><button class="btn" id="showbookmarks">☆ Избранное <b>${Object.values(bookmarks).filter(Boolean).length}</b></button><button class="btn" id="showdifficult">↻ Повторить сложное <b>${Object.values(difficult).filter(Boolean).length}</b></button><button class="btn" id="exportprogress">↓ Сохранить прогресс</button><label class="btn import-label">↑ Восстановить <input type="file" id="importprogress" accept="application/json" hidden></label></div><h2>Библиотека тем</h2><div class="toolbar"><input id="search" class="search" placeholder="⌕ Найти тему или термин…" value="${esc(query)}">${categories.map(c=>`<button class="chip ${filter===c?'active':''}" data-cat="${c}">${c}</button>`).join('')}</div><div id="topiclist"></div><p class="source">Основа: «Микра билеты с пояснениями» (89 страниц). Дополнительная справка: <a target="_blank" href="https://openstax.org/books/microbiology/pages/1-introduction">OpenStax Microbiology</a>. Учебный материал требует проверки преподавателем перед экзаменом.</p>`;$('#search').oninput=e=>{query=e.target.value;drawList()};document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{filter=b.dataset.cat;home()});$('#showbookmarks').onclick=()=>{filter='Избранное';drawList()};$('#showdifficult').onclick=()=>{filter='Сложное';drawList()};$('#exportprogress').onclick=exportProgress;$('#importprogress').onchange=importProgress;drawList()}
function drawList(){const items=topics.filter(t=>(filter==='Все'||t.section===filter||(filter==='Избранное'&&bookmarks[topicId(t)])||(filter==='Сложное'&&difficult[topicId(t)]))&&(t.title+' '+t.body.slice(0,2000)).toLowerCase().includes(query.toLowerCase()));$('#topiclist').innerHTML=items.length?`<div class="tiles">${items.map(t=>`<button class="tile" data-id="${t.uid}"><div class="number">${progress[topicId(t)]?'✓ ПРОЙДЕНО':'ТЕМА '+String(t.uid+1).padStart(2,'0')}</div><h3>${esc(t.title)}</h3><small>${esc(t.section)} · ${t.custom?'тест с выбором':'карточки + самопроверка'}</small></button>`).join('')}</div>`:'<div class="empty">Ничего не найдено. Попробуйте другой запрос.</div>';document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>lesson(topics.find(t=>t.uid==b.dataset.id)))}
function exportProgress(){const blob=new Blob([JSON.stringify({version:6,progress,bookmarks,difficult,spaced,ticketProgress,bankState,exported:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='micro-lab-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importProgress(e){
 const f=e.target.files?.[0];if(!f)return;
 try{
  if(f.size>1024*1024)throw Error('Большой размер');
  const d=JSON.parse(await f.text());
  const plain=o=>o&&typeof o==='object'&&!Array.isArray(o)&&Object.keys(o).length<3000;
  if(!d||![5,6].includes(d.version)||!plain(d.progress)||!plain(d.bookmarks||{})||!plain(d.difficult||{})||!plain(d.spaced||{})||!plain(d.ticketProgress||{})||!plain(d.bankState||{}))throw Error('Неверный формат');
  const normalize=obj=>Object.fromEntries(Object.entries(obj).filter(([k])=>/^[a-zA-Z0-9:_-]{1,100}$/.test(k)));
  const remap=obj=>{
   const r=normalize(obj||{});
   for(const [key,val] of Object.entries(r)){
    if(/^\d+$/.test(key)&&topics[+key]){r[topicId(topics[+key])]=val;delete r[key]}
   }
   return r;
  };
  // Back up current state before changing it, for recovery if the imported file was unexpected.
  const backup={version:6,progress,bookmarks,difficult,spaced,ticketProgress,bankState};
  localStorage.setItem('micro-progress-backup-before-import',JSON.stringify(backup));
  progress=remap(d.progress);bookmarks=remap(d.bookmarks);difficult=remap(d.difficult);
  spaced=normalize(d.spaced||{});
  for(const [key,val] of Object.entries({...spaced})){
   const m=/^(\d+):(\d+)$/.exec(key);
   if(m&&topics[+m[1]]){spaced[topicId(topics[+m[1]])+':'+m[2]]=val;delete spaced[key]}
  }
  ticketProgress=normalize(d.ticketProgress||{});
  if(d.bankState){bankState=normalize(d.bankState);saveBank()}
  saveTicketProgress();save();persistStudy();home();alert('Прогресс восстановлен; предыдущие данные сохранены в резервной копии браузера.');
 }catch(err){alert('Не удалось восстановить прогресс: проверьте формат файла (MICRO LAB)')}
 e.target.value='';
}
function simpleText(t){if(t.custom)return t.custom.simple;const lines=t.body.split(/(?<=[.!?])\s+/).filter(x=>x.length>35&&x.length<400).slice(0,7);return `Главная идея темы «${t.title}» — понять ключевые определения и их взаимосвязь. Ниже основные положения исходного конспекта:\n\n`+lines.join('\n\n')+'\n\nДля экзамена важно уметь объяснить термины своими словами и привести пример.'}
function scientificText(t){return t.custom?t.custom.scientific+'\n\nИз исходного конспекта:\n'+t.body.slice(0,2400):t.body}
function diagram(t){let steps=t.custom?.steps||['🔎|Объект изучения','🧪|Основные признаки','🧠|Объяснение механизма','✓|Вывод'];return `<div class="diagram"><div class="diagram-title">◈ ${t.custom?'Схема механизма':'План изучения темы'}: ${esc(t.title)}</div><div class="diagram-flow">${steps.map((v,i)=>{let [emoji,label]=v.split('|');return `<div class="node"><b>${emoji}</b><span>${esc(label)}</span></div>`}).join('')}</div><p class="muted small" style="margin-top:16px">Нажимайте на этапы, чтобы выделить их и проследить последовательность.</p></div>`}
function modelKind(t){const n=t.title.toLowerCase();if(/иммунитет|фагоцит|комплемент/.test(n))return 'immune';if(/дыхани|метаболизм|питани|типу питания/.test(n))return 'energy';if(/диагностик|отбор материала|реакци|рп по асколи|ра на стекле/.test(n))return 'lab';if(/инфекци|передачи/.test(n))return 'infection';return null}
const modelLibrary={
immune:{title:'Как организм обезвреживает бактерию',stages:[['Барьер','Микроорганизм приближается к защитному барьеру кожи или слизистой.'],['Распознавание','После преодоления барьера клетки врождённого иммунитета распознают чужеродные структуры.'],['Фагоцитоз','Фагоцит захватывает бактерию и помещает её в фагосому.'],['Разрушение','Фагосома сливается с лизосомой; бактерия разрушается.']]},
energy:{title:'От питательного вещества к АТФ',stages:[['Поступление','Питательное вещество попадает в клетку.'],['Катаболизм','Субстрат преобразуется в ходе ферментативных реакций.'],['АТФ','Часть освобождённой энергии сохраняется в форме АТФ.'],['Биосинтез','АТФ используется в энергозатратных клеточных процессах.']]},
lab:{title:'От образца к лабораторному заключению',stages:[['Образец','Материал отбирают с соблюдением требований к качеству и безопасности.'],['Исследование','К образцу применяют подходящий лабораторный метод.'],['Контроль','Контрольные образцы помогают оценить корректность исследования.'],['Заключение','Результат интерпретируют с учётом клинического контекста.']]},
infection:{title:'Как прерывается цепочка инфекции',stages:[['Источник','В источнике находится возбудитель.'],['Выделение','Возбудитель покидает источник инфекции.'],['Передача','Реализуется соответствующий механизм передачи.'],['Новый хозяин','Возбудитель достигает восприимчивого организма.']]}
};
